import { useState } from "react";

function Signup() {
  const [user, setuser] = useState({
    id : "",
    name : "",
    email : "",
    password : "",

  });
  const handleSubmit = async(e) => {
    e.preventDefault();
    await fetch("https://localhost:8000/student/signup",{
      method: "POST",
      headers: {
        "content-Type":"application/json",
      },
      body: JSON.stringify(user),     
    });
    alert("signup succesfully");    
  };

  return (
    <from onSubmit={handleSubmit}>
      <input placeholder="ID" onChangeCapture={(e)=>setuser({...user,id:e.target.value})}/>
      <input placeholder="NAME" onChange={(e)=>setuser({...user,name:e.target.value})}/>
      <input placeholder= "EMAIL" onChangeCapture={(e)=>setuser({...user.email.e.target.value})}/>
      <input type= "password" placehoder="password" onChange={(e)=>setuser({...user,password:e.target.value})}/>
      <button type="submit">Sign up</button>
    </from>
  );
}

export default Signup;
